<template><div class="recharge"><h2>充值中心</h2><p>充值规则：1 元 = 10 金币，1 金币可添加 1 个藏宝阁账号。</p><el-card v-for="p in plans" :key="p.id" class="plan"><h3>{{ p.name }}</h3><p>{{ p.description }}</p><strong>¥{{ (p.amountFen/100).toFixed(2) }}</strong><el-button type="primary" @click="buy(p.id)">微信支付</el-button></el-card><el-alert v-if="message" :title="message" type="info" :closable="false" /></div></template>
<script setup lang="ts">const plans = ref<any[]>([]); const message = ref(''); onMounted(async () => { plans.value = (await $fetch<any>('/api/plans')).plans }); const buy = async (planId: string) => { const r:any = await $fetch('/api/payment/create', { method:'POST', body:{ planId } }); message.value = r.message || `订单号：${r.orderNo}` }</script>
<style scoped>.recharge{max-width:720px;margin:30px auto}.plan{margin:12px 0}.plan strong{display:inline-block;margin-right:20px;color:#e53935;font-size:20px}</style>
